import{d as A,C as d,o as B,c as E,j as n,a as i,E as e,a3 as I}from"./chunks/framework.D4-ViStF.js";const U=JSON.parse('{"title":"庄子·天地","description":"洋洋乎大哉初有无论到机心论与失性五者，理解庄子外篇结构最完整的篇章。","frontmatter":{"title":"庄子·天地","description":"洋洋乎大哉初有无论到机心论与失性五者，理解庄子外篇结构最完整的篇章。","category":"guide","aliases":["天地","庄子天地","zhuangzi chapter 12"],"source":["《庄子·天地》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-12.md","filePath":"daoism/zhuang-zi/chapter-12.md","lastUpdated":1788516578000}'),K={name:"daoism/zhuang-zi/chapter-12.md"},F=A({...K,setup(L){const l=[{id:"dejian",sentences:[["天地虽大，其化均也；万物虽多，其治一也；人卒虽众，其主君也。君原于德而成于天。故曰：",{text:"玄古之君天下",glossary:"xuangu"},"，无为也，",{text:"天德而已矣",glossary:"tiande"},"。"],["以道观言而天下之君正；以道观分而君臣之义明；以道观能而天下之官治；以道泛观而万物之应备。"],["故通于天地者，德也；行于万物者，道也；上治人者，事也；能有所艺者，技也。",{text:"技兼于事，事兼于义，义兼于德，德兼于道，道兼于天",glossary:"jian"},'。故曰：古之畜天下者，无欲而天下足，无为而万物化，渊静而百姓定。《记》曰："通于一而万事毕，无心得而鬼神服。"']]}],p=[{id:"xuangu",term:"玄古之君天下",pinyin:"xuán gǔ zhī jūn tiān xià",meaning:"玄古：远古；君天下：治理天下。远古治理天下的君，是无为的。"},{id:"tiande",term:"天德而已矣",pinyin:"tiān dé ér yǐ yǐ",meaning:"以天德（自然之德）行事而已。不是积极治理，而是顺应自然，不加干涉。"},{id:"jian",term:"技兼于事……道兼于天",pinyin:"jì jiān yú shì……dào jiān yú tiān",meaning:"兼：统摄、……道→天，每一层都统摄于更高层，构成《天地》全篇的哲学骨架。"},{id:"xutianxia",term:"畜天下者",pinyin:"xù tiān xià zhě",meaning:"畜：养育、蓄养。古代养育天下的人（真正的治者）。不是「治天下」，而是「畜天下」。"}],o=[{id:"kuxin",sentences:[['夫子曰："夫道，覆载万物者也，洋洋乎大哉！君子不可以不',{text:"刳心",glossary:"kuxin"},"焉。",{text:"无为为之之谓天",glossary:"wuweiwei"},"，无为言之之谓德，爱人利物之谓仁，不同同之之谓大，行不崖异之谓宽，有万不同之谓富。"],["故执德之谓纪，德成之谓立，循于道之谓备，不以物挫志之谓完。君子明于此十者，则韬乎其事心之大也，沛乎其为万物逝也。"],["若然者，藏金于山，藏珠于渊；不利货财，不近贵富；不乐寿，不哀夭；不荣通，不丑穷。不拘一世之利以为己私分，不以王天下为己处显。显则明。万物一府，死生同状。"],['夫子曰："夫道，渊乎其居也，漻乎其清也。金石不得无以鸣。故金石有声，不考不鸣。万物孰能定之！夫',{text:"王德之人",glossary:"wangde"},"，素逝而耻通于事，立之本原而知通于神，故其德广。其心之出，有物采之。"],['故形非道不生，生非德不明。存形穷生，立德明道，非王德者邪！荡荡乎！忽然出，勃然动，而万物从之乎！此谓王德之人。视乎冥冥，听乎无声。冥冥之中，独见晓焉；无声之中，独闻和焉。故深之又深而能物焉；神之又神而能精焉。故其与万物接也，至无而供其求，时骋而要其宿，大小、长短、修远。"']]}],m=[{id:"kuxin",term:"刳心",pinyin:"kū xīn",meaning:"刳：剖开、挖空。刳心：挖空心中的成见与执着，使心虚空以容道。不是往心里装东西，而是把心里的东西挖空。"},{id:"wuweiwei",term:"无为为之之谓天",pinyin:"wú wéi wéi zhī zhī wèi tiān",meaning:"以无为的方式去做，叫做天（天道）。不是不做，而是做的方式是无为的。"},{id:"wangde",term:"王德之人",pinyin:"wàng dé zhī rén",meaning:"王德：最高的德，得道之人的德。王德之人：拥有最高德性的人。"}],g=[{id:"xuanzhu",sentences:[["黄帝游乎赤水之北，登乎昆仑之丘而南望。还归，",{text:"遗其玄珠",glossary:"xuanzhu"},"。"],["使",{text:"知",glossary:"zhi"},"索之而不得，使",{text:"离朱",glossary:"lizhu"},"索之而不得，使",{text:"喫诟",glossary:"chigou"},"索之而不得也。"],["乃使",{text:"象罔",glossary:"xiangwang"},'，象罔得之。黄帝曰："异哉，象罔乃可以得之乎？"']]}],h=[{id:"xuanzhu",term:"遗其玄珠",pinyin:"yí qí xuán zhū",meaning:"遗：遗失。玄珠：黑色的珠，象征道（玄：深远幽暗，道的颜色）。黄帝遗失了玄珠，就是遗失了道。"},{id:"zhi",term:"知",pinyin:"zhī",meaning:"智慧、机巧之知。派智慧去寻找——不得。"},{id:"lizhu",term:"离朱",pinyin:"lí zhū",meaning:"传说中视力极佳的人，能在百步之外看清秋毫之末。象征极致的视觉感知——不得。"},{id:"chigou",term:"喫诟",pinyin:"chī gòu",meaning:"传说中善于辩论的人。象征极致的辩论能力——不得。"},{id:"xiangwang",term:"象罔",pinyin:"xiàng wǎng",meaning:"象：形象、有形；罔：无、虚无。象罔：有形与无形之间，若有若无的状态。象征无心、无执的状态——得之。"}],y=[{id:"xuanyou",sentences:[['尧之师曰许由，许由之师曰啮缺，啮缺之师曰王倪，王倪之师曰被衣。尧问于许由曰："啮缺可以',{text:"配天",glossary:"peitian"},'乎？吾藉王倪以要之。"'],['许由曰："',{text:"殆哉，圾乎天下",glossary:"daizai"},"！啮缺之为人也，聪明睿知，给数以敏，其性过人，而又乃",{text:"以人受天",glossary:"yirenshoutian"},"。彼审乎禁过，而不知过之所由生。"],["与之配天乎？彼且",{text:"乘人而无天",glossary:"chengren"},"。方且本身而异形，方且尊知而火驰，方且为绪使，方且为物絯，方且四顾而物应，方且应众宜，方且与物化而未始有恒。夫何足以配天乎！"],['虽然，有族有祖，可以为众父而不可以为众父父。治，乱之率也，北面之祸也，南面之贼也。"']]}],u=[{id:"peitian",term:"配天",pinyin:"pèi tiān",meaning:"与天相配，成为天子（治理天下）。"},{id:"daizai",term:"殆哉，圾乎天下",pinyin:"dài zāi，jí hū tiān xià",meaning:"殆：危险；圾：危险、不稳。危险啊，天下岌岌可危！"},{id:"yirenshoutian",term:"以人受天",pinyin:"yǐ rén shòu tiān",meaning:"以人（人为的标准）来接受天（天道）。用人的框架来理解天道——这是根本性的错误。"},{id:"chengren",term:"乘人而无天",pinyin:"chéng rén ér wú tiān",meaning:"依靠人（人为的能力）而没有天（天道）。"}],x=[{id:"huafeng",sentences:[['尧观乎华，华封人曰："嘻，圣人！请祝圣人，使圣人寿。"尧曰："辞。""使圣人富。"尧曰："辞。""使圣人多男子。"尧曰："辞。"'],['封人曰："寿，富，多男子，人之所欲也。女独不欲，何邪？"尧曰："多男子则多惧，富则多事，寿则多辱。是三者，非所以养德也，故辞。"'],['封人曰："始也我以女为圣人邪，今然君子也。天生万民，必授之职。多男子而授之职，则何惧之有？富而使人分之，则何事之有？夫圣人，',{text:"鹑居而彀食",glossary:"chunju"},'，鸟行而无彰。天下有道，则与物皆昌；天下无道，则修德就闲。千岁厌世，去而上仙，乘彼白云，至于帝乡。三患莫至，身常无殃，则何辱之有？"'],['封人去之，尧随之曰："请问。"封人曰："退已！"']]}],b=[{id:"chunju",term:"鹑居而彀食",pinyin:"chún jū ér gòu shí",meaning:"鹑居：像鹌鹑一样居处（随遇而安，不固定）；彀食：像幼鸟一样进食（随时取食，不积储）。不执着于居所，不积储食物。"}],c=[{id:"bocheng",sentences:[["尧治天下，伯成子高立为诸侯。尧授舜，舜授禹，伯成子高辞为诸侯而耕。"],['禹往见之，则耕在野。禹趋就下风，立而问焉，曰："昔尧治天下，吾子立为诸侯。尧授舜，舜授予，而吾子辞为诸侯而耕。敢问其故何也？"'],['子高曰："昔者尧治天下，不赏而民劝，不罚而民畏。今子赏罚而民且不仁，德自此衰，刑自此立，后世之乱自此始矣！',{text:"夫子阖行邪？无落吾事",glossary:"hehang"},'"',{text:"俋俋乎耕而不顾",glossary:"yiyihu"},"。"]]}],f=[{id:"hehang",term:"夫子阖行邪？无落吾事",pinyin:"fū zǐ hé xíng xié？wú luò wú shì",meaning:"阖：何不、还是。你还是走吧！不要耽误我的事！落：耽误、妨碍。"},{id:"yiyihu",term:"俋俋乎耕而不顾",pinyin:"yì yì hū gēng ér bù gù",meaning:"俋俋：埋头耕作的样子。埋头耕作，头也不回。"}],k=[{id:"taichu",sentences:[["泰初有无，无有无名。",{text:"一之所起",glossary:"yisuoqi"},"，有一而未形。"],[{text:"物得以生谓之德",glossary:"wudeyisheng"},"；未形者有分，且然无间谓之命；留动而生物，物成生理谓之形；形体保神，各有仪则谓之性；"],[{text:"性修反德",glossary:"xingxiufande"},"，德至同于初。同乃虚，虚乃大。合喙鸣。喙鸣合，与天地为合。其合缗缗，若愚若昏，是谓玄德，同乎大顺。"]]}],z=[{id:"yisuoqi",term:"一之所起",pinyin:"yī zhī suǒ qǐ",meaning:'"一"（道的本体）开始生起的地方。泰初有无，无有无名；一之所起，有一而未形——从无到有的第一步。'},{id:"wudeyisheng",term:"物得以生谓之德",pinyin:"wù dé yǐ shēng wèi zhī dé",meaning:"万物得到（道）而能够生长，这叫做德。不是道德的德，而是道在万物中的体现，道给予万物的生长能力。"},{id:"xingxiufande",term:"性修反德",pinyin:"xìng xiū fǎn dé",meaning:"修养本性，返回于德。不是抛弃形体，而是在形体之中修养本性，自然回归到泰初的虚大。"}],P=[{id:"laodan",sentences:[[`夫子问于老聃曰："有人治道若相放，可不可，然不然。辩者有言曰：'离坚白，若县寓。'若是则可谓圣人乎？"`],['老聃曰："是',{text:"胥易技系",glossary:"xuyi"},"，劳形怵心者也。执留之狗成思，猿狙之便自山林来。丘，予告若，而所不能闻与而所不能言：凡有首有趾、无心无耳者众；有形者与无形无状而皆存者尽无。其动止也，其死生也，其废起也，此又非其所以也。有治在人。",{text:"忘乎物，忘乎天，其名为忘己",glossary:"wangji"},'。忘己之人，是之谓入于天。"'],[`将闾葂见季彻曰："鲁君谓葂也曰：'请受教。'辞不获命。既已告矣，未知中否。请尝荐之。吾谓鲁君曰：'必服恭俭，拔出公忠之属而无阿私，民孰敢不辑！'"`],['季彻局局然笑曰："若夫子之言，于帝王之德，犹螳螂之怒臂以当车轶，则必不胜任矣！且若是，则其自为处危，其观台多物，将往投迹者众。"'],['将闾葂覷觑然惊曰："葂也汒若于夫子之所言矣！虽然，愿先生之言其风也。"季彻曰："大圣之治天下也，摇荡民心，使之成教易俗，举灭其贼心而皆进其独志。若性之自为，而民不知其所由然。若然者，岂兄尧、舜之教民溟涬然弟之哉？欲同乎德而心居矣！"']]}],q=[{id:"xuyi",term:"胥易技系",pinyin:"xū yì jì xì",meaning:"胥：相互；易：变换；技：技巧；系：束缚。相互变换技巧，被技巧所束缚。辩者以为在追求道，实则被自己的辩论技巧所束缚。"},{id:"wangji",term:"忘乎物，忘乎天，其名为忘己",pinyin:"wàng hū wù，wàng hū tiān，qí míng wéi wàng jǐ",meaning:"忘掉外物，忘掉天，这叫做忘己。忘己的人，这叫做进入天（与天合一）。"}],w=[{id:"jixin",sentences:[["子贡南游于楚，反于晋，过汉阴，见一丈人方将为圃畦，凿隧而入井，抱瓮而出灌，搰然用力甚多而见功寡。"],['子贡曰："有械于此，一日浸百畦，用力甚寡而见功多，夫子不欲乎？"为圃者仰而视之曰："奈何？"曰："凿木为机，后重前轻，挈水若抽，数如泆汤，其名为槔。"'],['为圃者忿然作色而笑曰："吾闻之吾师，有机械者必有机事，有机事者必有机心。',{text:"机心存于胸中则纯白不备",glossary:"jixin"},'。纯白不备则神生不定，神生不定者，道之所不载也。吾非不知，羞而不为也。"'],['子贡瞒然惭，俯而不对。有间，为圃者曰："子奚为者邪？"曰："孔丘之徒也。"为圃者曰："子非夫博学以拟圣，於于以盖众，独弦哀歌以卖名声于天下者乎？汝方将忘汝神气，堕汝形骸，而庶几乎！而身之不能治，而何暇治天下乎！子往矣，无乏吾事。"'],['子贡卑陬失色，顼顼然不自得，行三十里而后愈。其弟子曰："向之人何为者邪？夫子何故见之变容失色，终日不自反邪？"'],['曰："始吾以为天下一人耳，不知复有夫人也。吾闻之夫子：事求可，功求成，用力少，见功多者，圣人之道。今徒不然。执道者德全，德全者形全，形全者神全。神全者，圣人之道也。托生与民并行而不知其所之，汒乎淳备哉！功利机巧必忘夫人之心。'],["若夫人者，非其志不之，非其心不为。虽以天下誉之，得其所谓，謷然不顾；以天下非之，失其所谓，傥然不受。天下之非誉无益损焉，是谓",{text:"全德之人",glossary:"quande"},'哉！我之谓风波之民。"'],['反于鲁，以告孔子。孔子曰："彼假修',{text:"浑沌氏之术",glossary:"hundunshi"},'者也。识其一，不识其二；治其内而不治其外。夫明白入素，无为复朴，体性抱神，以游世俗之间者，汝将固惊邪？且浑沌氏之术，予与汝何足以识之哉！"']]}],j=[{id:"jixin",term:"机心存于胸中则纯白不备",pinyin:"jī xīn cún yú xiōng zhōng zé chún bái bù bèi",meaning:"机心：机巧算计之心。机心一旦进入内心，纯白（本真的心）就不完备了。纯白不备则神生不定，神生不定者，道之所不载也。"},{id:"quande",term:"全德之人",pinyin:"quán dé zhī rén",meaning:"德性完整的人。非其志不之，非其心不为。天下誉之，謷然不顾；天下非之，傥然不受。"},{id:"hundunshi",term:"浑沌氏之术",pinyin:"hún dùn shì zhī shù",meaning:"浑沌氏（上古帝王）的方术。孔子说丈人是修浑沌氏之术者——识其一，不识其二；治其内而不治其外。"}],T=[{id:"zhunmang",sentences:[['谆芒将东之大壑，适遇苑风于东海之滨。苑风曰："子将奚之？"曰："将之大壑。"曰："奚为焉？"曰："夫大壑之为物也，注焉而不满，酌焉而不竭。吾将游焉！"'],['苑风曰："夫子无意于横目之民乎？愿闻',{text:"圣治",glossary:"shengzhi"},'。"谆芒曰："圣治乎？官施而不失其宜，拔举而不失其能，毕见其情事而行其所为，行言自为而天下化。手挠顾指，四方之民莫不俱至，此之谓圣治。"'],['"愿闻',{text:"德人",glossary:"deren"},'。"曰："德人者，居无思，行无虑，不藏是非美恶。四海之内共利之之谓悦，共给之之谓安。怊乎若婴儿之失其母也，傥乎若行而失其道也。财用有余而不知其所自来，饮食取足而不知其所从，此谓德人之容。"'],['"愿闻',{text:"神人",glossary:"shenren"},'。"曰："上神乘光，与形灭亡，是谓照旷。致命尽情，天地乐而万事销亡，万物复情，此之谓混溟。"']]}],G=[{id:"shengzhi",term:"圣治",pinyin:"shèng zhì",meaning:"圣治：圣人的治理。官施而不失其宜，拔举而不失其能——让事物自然归位，而非强制安排。"},{id:"deren",term:"德人",pinyin:"dé rén",meaning:"德人：德性圆满的人。居无思，行无虑，不藏是非美恶。财用有余而不知其所自来——本然自足。"},{id:"shenren",term:"神人",pinyin:"shén rén",meaning:"神人：神妙的人。上神乘光，与形灭亡，是谓照旷。致命尽情，天地乐而万事销亡——与天地同流。"}],D=[{id:"zhideshi",sentences:[['门无鬼与赤张满稽观于武王之师，赤张满稽曰："不及有虞氏乎！故离此患也。"门无鬼曰："天下均治而有虞氏治之邪？其乱而后治之与？"'],['赤张满稽曰："天下均治之为愿，而何计以有虞氏为！',{text:"有虞氏之药疡也",glossary:"youyushi"},"，秃而施髢，病而求医。孝子操药以修慈父，其色燋然，圣人羞之。"],["至德之世，不尚贤，不使能，上如标枝，民如野鹿。",{text:"端正而不知以为义",glossary:"duanzheng"},'，相爱而不知以为仁，实而不知以为忠，当而不知以为信，蠢动而相使不以为赐。是故行而无迹，事而无传。"']]}],C=[{id:"youyushi",term:"有虞氏之药疡也",pinyin:"yǒu yú shì zhī yào yáng yě",meaning:"有虞氏（舜）治理天下，就像给疮疡上药——天下已经坏了，才来治。秃而施髢（秃了才戴假发），病而求医。治标，不治本。"},{id:"duanzheng",term:"端正而不知以为义",pinyin:"duān zhèng ér bù zhī yǐ wéi yì",meaning:"端正，却不知道这叫义。至德之世的特征：行为本然端正，但不知道这些有名字——一旦有了名字，成了概念，本然就消失了。"}],v=[{id:"dahuolun",sentences:[["孝子不谀其亲，忠臣不谄其君，臣、子之盛也。亲之所言而然，所行而善，则世俗谓之不肖子；君之所言而然，所行而善，则世俗谓之不肖臣。而未知此其必然邪？"],["世俗之所谓然而然之，所谓善而善之，则不谓之道谀之人也！然则俗故严于亲而尊于君邪？谓己道人，则勃然作色；谓己谀人，则怫然作色。而终身道人也，终身谀人也，合譬饰辞聚众也，是终始本末不相坐。"],["垂衣裳，设采色，动容貌，以媚一世，而不自谓道谀；与夫人之为徒，通是非，而不自谓众人也，愚之至也。"],["知其愚者，非大愚也；知其惑者，非大惑也。大惑者，终身不解；大愚者，终身不灵。三人行而一人惑，所适者，犹可致也，惑者少也；二人惑则劳而不至，惑者胜也。而今也以天下惑，予虽有祈向，不可得也。不亦悲乎！"],["大声不入于里耳，折杨、皇荂，则嗑然而笑。是故高言不止于众人之心；至言不出，俗言胜也。以二缶钟惑，而所适不得矣。而今也以天下惑，予虽有祈向，其庸可得邪！知其不可得也而强之，又一惑也！故莫若释之而不推。不推，谁其比忧！厉之人，夜半生其子，遽取火而视之，汲汲然唯恐其似己也。"]]}],N=[],V=[{id:"shixing",sentences:[["百年之木，破为",{text:"牺尊",glossary:"xizun"},"，青黄而文之，其断在沟中。比牺尊于沟中之断，则美恶有间矣，其于",{text:"失性",glossary:"shixing"},"一也。跖与曾、史，行义有间矣，然其失性均也。"],["且夫失性有五：一曰五色乱目，使目不明；二曰五声乱耳，使耳不聪；三曰五臭熏鼻，困惾中颡；四曰五味浊口，使口厉爽；五曰趣舍滑心，使性飞扬。此五者，皆生之害也。"],["而杨、墨乃始离跂自以为得，非吾所谓得也。夫得者困，可以为得乎？则鸠鸮之在于笼也，亦可以为得矣。"],["且夫趣舍声色以柴其内，皮弁鹬冠搢笏绅修以约其外。内支盈于柴栅，外重纆缴睆睆然在纆缴之中，而自以为得，则是罪人交臂历指而虎豹在于囊槛，亦可以为得矣！"]]}],R=[{id:"xizun",term:"牺尊",pinyin:"xī zūn",meaning:"雕刻有牛形的祭祀酒器。百年之木，破为牺尊——无论精美还是粗陋，都不再是那棵百年大树了。"},{id:"shixing",term:"失性",pinyin:"shī xìng",meaning:"失去本性。牺牲与沟中断木，美恶有别，其于失性一也。"}];return(J,a)=>{const S=d("DaoReadingPrelude"),t=d("DaoTextReading"),s=d("DaoKeywordCards"),r=d("DaoLineGuide");return B(),E("div",null,[a[0]||(a[0]=n("h1",{id:"庄子·天地",tabindex:"-1"},[i("庄子·天地 "),n("a",{class:"header-anchor",href:"#庄子·天地","aria-label":'Permalink to "庄子·天地"'},"​")],-1)),a[1]||(a[1]=n("h2",{id:"篇名释义",tabindex:"-1"},[i("篇名释义 "),n("a",{class:"header-anchor",href:"#篇名释义","aria-label":'Permalink to "篇名释义"'},"​")],-1)),a[2]||(a[2]=n("blockquote",null,[n("p",null,[n("strong",null,"《天地》是《庄子》外篇第五篇，也是外篇中篇幅最长、内容最丰富的一篇。")]),n("p",null,"篇名「天地」——不是说天地本身，而是说：以天地为参照，来理解道·德·人·治。"),n("p",null,"《天地》承接《在宥》——《在宥》的核心命题是「闻在宥天下，不闻治天下也」；《天地》的核心命题是「古之畜天下者，无欲而天下足，无为而万物化」。两篇，是同一个命题的两个方向：《在宥》说：不要治天下；《天地》说：真正的「畜天下」，是无欲无为。"),n("p",null,"《天地》的特色，在于它的层次感——从宇宙生成（泰初有无），到政治哲学（古之畜天下者），到个人修养（刳心·王德·全德），到具体批判（机心·失性五者）——是《庄子》外篇中结构最完整的一篇。")],-1)),e(S,{title:"从德兼于道到泰初有无、机心与失性五者",summary:"《天地》以「技兼于事，事兼于义，义兼于德，德兼于道，道兼于天」的层级为哲学骨架，展开外篇第五篇的完整结构：宇宙生成（泰初有无）、政治哲学（畜天下者无欲无为）、个人修养（刳心·王德·全德）、具体批判（象罔得玄珠、机心纯白、失性五者）。",points:[{label:"先看",text:"顺着德兼于道→刳心十者→玄珠→许由→华封→伯成子高→泰初→机心→至德之世→大惑→失性五者这条线走一遍。"},{label:"再问",text:"「象罔」为什么能找回玄珠？知、离朱、喫诟为什么都不行？"},{label:"最后",text:"「机心存于胸中则纯白不备」——今天的你，还在用桔槔灌园吗？"}],hint:"这是外篇结构最完整的一篇。读的时候可以不断回看《在宥》——两篇是同一个命题的两个方向。"}),a[3]||(a[3]=n("h2",{id:"一、德兼于道·道兼于天",tabindex:"-1"},[i("一、德兼于道·道兼于天 "),n("a",{class:"header-anchor",href:"#一、德兼于道·道兼于天","aria-label":'Permalink to "一、德兼于道·道兼于天"'},"​")],-1)),a[4]||(a[4]=n("h3",{id:"原文",tabindex:"-1"},[i("原文 "),n("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),e(t,{sections:l,glossary:p,"default-mode":"classic","aria-label":"天地·德兼于道 原文"}),a[5]||(a[5]=n("h3",{id:"生僻字词",tabindex:"-1"},[i("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"其化均也",pinyin:["jūn"],meaning:"均：均一、一致。它的化育是均一的（天地化育万物，没有偏私）。"},{term:"其治一也",pinyin:["qí","zhì","yī","yě"],meaning:"它的主宰是同一个（万物虽多，都受同一个道的主宰）。"},{term:"人卒虽众",pinyin:["rén","zú"],meaning:"人卒：人群、众人。人群虽然众多。"},{term:"天德而已矣",pinyin:["tiān","dé","ér","yǐ","yǐ"],meaning:"以天德（自然之德）行事而已。"},{term:"以道观言",pinyin:["yǐ","dào","guān","yán"],meaning:"用道来观察言论。"},{term:"以道观分",pinyin:["fèn"],meaning:"分：名分、职分。用道来观察名分。"},{term:"以道观能",pinyin:["yǐ","dào","guān","néng"],meaning:"用道来观察才能。"},{term:"以道泛观",pinyin:["fàn"],meaning:"泛：广泛、全面。用道来广泛观察。"},{term:"技兼于事",pinyin:["jiān"],meaning:"兼：统摄于、包含于。技，统摄于事之中。"},{term:"道兼于天",pinyin:["dào","jiān","yú","tiān"],meaning:"道，统摄于天之中。"}]}),a[6]||(a[6]=n("h3",{id:"核心句引读",tabindex:"-1"},[i("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"天地虽大，其化均也——以天地为参照",subtitle:"君，不是层级的顶端——君，是德与天在人间的体现。",lines:[{text:"天地虽大，其化均也；万物虽多，其治一也；人卒虽众，其主君也。君原于德而成于天。",tone:"总纲",guide:"《天地》开篇，三个「虽……其……」——构成全篇的哲学总纲：天地虽大，其化均也（天地化育万物，没有偏私，一视同仁）；万物虽多，其治一也（万物再多，都受同一个道的主宰——多，是表象；一，是根本）；人卒虽众，其主君也（人，以君为主）。君原于德而成于天——君，根源于德，成就于天。这四句，建立了《天地》的基本层级：天→道→德→君→人卒。君，不是层级的顶端——君，是德与天在人间的体现——君的权威，来自德与天，而不来自自身。"},{text:"技兼于事，事兼于义，义兼于德，德兼于道，道兼于天。",tone:"层级",guide:"这五句，是第一段最重要的命题——技，统摄于事之中；事，统摄于义之中；义，统摄于德之中；德，统摄于道之中；道，统摄于天之中。「兼」——统摄、包含、归属——每一个低层次，都统摄于更高层次之中。这个层级，有两层含义：归属关系（每一个层次都不能脱离更高层次而独立存在）与优先关系（高层次永远优先于低层次）。这个层级，是《天地》全篇的哲学骨架——当人只关注技·事，而忘记德·道·天——这，就是《天地》批判的根源。"},{text:"故曰：古之畜天下者，无欲而天下足，无为而万物化，渊静而百姓定。",tone:"畜天下",guide:"第一段的结论——古之畜天下者——古代养育天下的人——「畜」——养育、蓄养——不是「治天下」，而是「畜天下」——这与《在宥》「在宥天下」完全一致。无欲而天下足——不是「努力让天下充足」，而是「没有欲望，天下自然就充足了」——欲望，是天下不足的根源；无为而万物化——有为，是万物不化的根源；渊静而百姓定——躁动，是百姓不定的根源。三句，结构完全一致：无……而……自然……——不是主动去做，而是通过「不做」，让结果自然出现。"}]}),a[7]||(a[7]=n("h2",{id:"二、夫子论道·刳心十者·王德之人",tabindex:"-1"},[i("二、夫子论道·刳心十者·王德之人 "),n("a",{class:"header-anchor",href:"#二、夫子论道·刳心十者·王德之人","aria-label":'Permalink to "二、夫子论道·刳心十者·王德之人"'},"​")],-1)),a[8]||(a[8]=n("h3",{id:"原文-1",tabindex:"-1"},[i("原文 "),n("a",{class:"header-anchor",href:"#原文-1","aria-label":'Permalink to "原文"'},"​")],-1)),e(t,{sections:o,glossary:m,"default-mode":"classic","aria-label":"天地·刳心十者 原文"}),a[9]||(a[9]=n("h3",{id:"生僻字词-1",tabindex:"-1"},[i("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"洋洋乎大哉",pinyin:["yáng","yáng"],meaning:"洋洋：广大无边的样子。广大无边啊！"},{term:"刳心",pinyin:["kū","xīn"],meaning:"刳：剖开、挖空。刳心：挖空心中的成见与执着，使心虚空以容道。"},{term:"执德之谓纪",pinyin:["jì"],meaning:"纪：纲纪、准则。执守德，叫做纪（有了准则）。"},{term:"德成之谓立",pinyin:["dé","chéng","zhī","wèi","lì"],meaning:"德性成就，叫做立（有所建立）。"},{term:"王德之人",pinyin:["wàng","dé"],meaning:"王德：最高的德。王德之人：拥有最高德性的人，得道之人。"}]}),a[10]||(a[10]=n("h3",{id:"核心句引读-1",tabindex:"-1"},[i("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"君子不可以不刳心焉",subtitle:"不是往心里装东西——而是把心里的东西挖空——心越空，道越能进入。",lines:[{text:"夫道，覆载万物者也，洋洋乎大哉！君子不可以不刳心焉。",tone:"刳心",guide:"第二段，以「夫子曰」开始——夫道，覆载万物者也（道，是覆盖并承载万物的——覆：天覆；载：地载——道，既是天，又是地——万物，在道之中）。洋洋乎大哉！君子不可以不刳心焉——「刳心」——刳：剖开、挖空——刳心：挖空心中的成见与执着，使心虚空，以容纳道。这是《天地》对「修道」的核心表述：不是往心里装东西——而是把心里的东西挖空——心越空，道越能进入——这与《人间世》「心斋」完全呼应：「唯道集虚，虚者，心斋也。」"},{text:"无为为之之谓天，无为言之之谓德，爱人利物之谓仁，不同同之之谓大，行不崖异之谓宽，有万不同之谓富。",tone:"六定义",guide:"六句，定义六个概念——天·德·仁·大·宽·富。庄子的六个定义，与儒家的定义有根本的不同：儒家的仁·大·宽·富，都是积极的、主动的、需要努力实现的；庄子的仁·大·宽·富，都是包容的、顺应的、以「不……」为特征的——不同同之（不强求相同，而是在差异中达到大同——包容差异，才是真正的大），行不崖异（不刻意标新立异，才是真正的宽广），有万不同（真正的富，不是财富的积累——而是包容万种差异的能力）。"},{text:"故执德之谓纪，德成之谓立，循于道之谓备，不以物挫志之谓完。",tone:"四递进",guide:"四句，再定义四个概念——纪·立·备·完，构成一个递进：纪（有准则）→立（有建立）→备（完备）→完（完整）。「不以物挫志之谓完」——这一句，是四者中最重要的：完整，不是外在的完整——而是：内在的志向不被外物所挫伤——这，才是真正的完整。外物，永远在变化——真正的完整，在于内在的志向不被外物所动。"},{text:"视乎冥冥，听乎无声。冥冥之中，独见晓焉；无声之中，独闻和焉。",tone:"冥冥",guide:"王德之人——荡荡乎！忽然出，勃然动，而万物从之乎！——不是刻意的，不是预谋的——这种「突然」，是自然的流露。视乎冥冥，听乎无声——向幽暗深远之处观看，向无声之处聆听——冥冥之中，独见晓焉（不是在光明中看见光明——而是在幽暗中，独自见到光明——这种「见」，不是感官的见，而是道的见）；无声之中，独闻和焉（不是在声音中听见和谐——而是在无声中，独自听到和谐）。这与广成子「无视无听，抱神以静」完全呼应：不用感官，而用道——在感官无法到达的地方，道独自见到、听到。"}]}),a[11]||(a[11]=n("h2",{id:"三、黄帝遗玄珠·象罔得之",tabindex:"-1"},[i("三、黄帝遗玄珠·象罔得之 "),n("a",{class:"header-anchor",href:"#三、黄帝遗玄珠·象罔得之","aria-label":'Permalink to "三、黄帝遗玄珠·象罔得之"'},"​")],-1)),a[12]||(a[12]=n("h3",{id:"原文-2",tabindex:"-1"},[i("原文 "),n("a",{class:"header-anchor",href:"#原文-2","aria-label":'Permalink to "原文"'},"​")],-1)),e(t,{sections:g,glossary:h,"default-mode":"classic","aria-label":"天地·黄帝遗玄珠 原文"}),a[13]||(a[13]=n("h3",{id:"生僻字词-2",tabindex:"-1"},[i("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"赤水之北",pinyin:["chì","shuǐ","zhī","běi"],meaning:"赤水：传说中的河流，昆仑山附近。"},{term:"昆仑之丘",pinyin:["kūn","lún"],meaning:"昆仑：传说中的神山，道的象征之地。"},{term:"遗其玄珠",pinyin:["yí","xuán","zhū"],meaning:"遗：遗失、丢失。玄珠：黑色的珠，象征道（玄：深远幽暗，道的颜色）。"},{term:"使知索之",pinyin:["zhī","suǒ"],meaning:"知：智慧、机巧之知。派智慧去寻找。"},{term:"离朱",pinyin:["lí","zhū"],meaning:"传说中视力极佳的人，能在百步之外看清秋毫之末。象征极致的视觉感知。"},{term:"喫诟",pinyin:["chī","gòu"],meaning:"传说中善于辩论的人。象征极致的辩论能力。"},{term:"象罔",pinyin:["xiàng","wǎng"],meaning:"象：形象、有形；罔：无、虚无。象罔：有形与无形之间，若有若无的状态。象征无心、无执的状态。"}]}),a[14]||(a[14]=n("h3",{id:"核心句引读-2",tabindex:"-1"},[i("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"异哉，象罔乃可以得之乎？",subtitle:"越主动地找，越找不到——因为「找」本身，就是一种执着。",lines:[{text:"使知索之而不得，使离朱索之而不得，使喫诟索之而不得也。乃使象罔，象罔得之。",tone:"四者",guide:"黄帝，派了三个人去寻找——知（智慧·机巧之知），不得；离朱（极致的视觉感知），不得；喫诟（极致的辩论能力），不得。三者，都没有找到——乃使象罔，象罔得之。四个人物，各有象征：知·离朱·喫诟——代表了人类最引以为傲的三种能力：智识、感知、辩论——这三种能力，在寻找道的时候，全部失败。为什么？因为道，是「玄珠」——玄：深远幽暗，不可以用智识把握；珠：圆满完整，不可以用感官分割。道，不是可以被「找」到的——越主动地找，越找不到——因为「找」本身，就是一种执着，而执着，与道相悖。"},{text:"乃使象罔，象罔得之。黄帝曰：异哉，象罔乃可以得之乎？",tone:"象罔",guide:"象罔——若有若无——象：有形象；罔：无、虚无——象罔，是有形与无形之间的状态——不完全有，不完全无——若有若无，无心无执。这种状态，才能找到玄珠——不是因为象罔更聪明，更有眼力，更善辩——而是因为：象罔，不执着于「找」——无心，才能得；有心，反而失。这与鸿蒙「若彼知之，乃是离之」完全呼应：越想知道道，越离开道——象罔，不想知道，反而得到了。黄帝的感叹「异哉」——是真正的惊异：他派出了最强的能力，全部失败——却被一个「若有若无」的象罔找到了——这，颠覆了黄帝对「能力」的全部认知。"}]}),a[15]||(a[15]=n("h2",{id:"四、尧问许由·啮缺不配天",tabindex:"-1"},[i("四、尧问许由·啮缺不配天 "),n("a",{class:"header-anchor",href:"#四、尧问许由·啮缺不配天","aria-label":'Permalink to "四、尧问许由·啮缺不配天"'},"​")],-1)),a[16]||(a[16]=n("h3",{id:"原文-3",tabindex:"-1"},[i("原文 "),n("a",{class:"header-anchor",href:"#原文-3","aria-label":'Permalink to "原文"'},"​")],-1)),e(t,{sections:y,glossary:u,"default-mode":"classic","aria-label":"天地·尧问许由 原文"}),a[17]||(a[17]=n("h3",{id:"生僻字词-3",tabindex:"-1"},[i("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"许由",pinyin:["xǔ","yóu"],meaning:"传说中的隐士，尧欲让天下于他而不受。尧的老师。"},{term:"啮缺",pinyin:["niè","quē"],meaning:"传说中的人物，许由的学生，王倪的老师。"},{term:"被衣",pinyin:["pī","yī"],meaning:"传说中的人物，王倪的老师。"},{term:"配天",pinyin:["pèi","tiān"],meaning:"与天相配，成为天子（治理天下）。"},{term:"聪明睿知",pinyin:["ruì","zhī"],meaning:"聪明：耳聪目明；睿：深远的智慧；知：机巧之知。极度聪明有智慧。"},{term:"给数以敏",pinyin:["jǐ","shuò"],meaning:"给：敏捷；数：频繁、迅速；敏：敏锐。反应敏捷迅速。"},{term:"其性过人",pinyin:["qí","xìng","guò","rén"],meaning:"他的才性超过常人。"},{term:"以人受天",pinyin:["yǐ","rén","shòu","tiān"],meaning:"以人（人为的标准）来接受天（天道）。用人的标准来理解天道。"},{term:"审乎禁过",pinyin:["shěn"],meaning:"审：审察、精通。精通于禁止过失。"},{term:"乘人而无天",pinyin:["chéng","rén","ér","wú","tiān"],meaning:"依靠人（人为的能力）而没有天（天道）。"},{term:"方且为绪使",pinyin:["xù","shǐ"],meaning:"绪：丝绪、线头（比喻纷繁的事务）。正在被纷繁事务所驱使。"},{term:"方且为物絯",pinyin:["gài"],meaning:"絯：绳索、束缚。正在被外物所束缚。"}]}),a[18]||(a[18]=n("h3",{id:"核心句引读-3",tabindex:"-1"},[i("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"殆哉，圾乎天下！——让啮缺配天，天下会有危险",subtitle:"越聪明，越忙碌；越忙碌，越被事务驱使；越被驱使，越失去恒常。",lines:[{text:"啮缺之为人也，聪明睿知，给数以敏，其性过人，而又乃以人受天。",tone:"以人受天",guide:"许由，先描述啮缺的优点——聪明睿知（极度聪明有智慧），给数以敏（反应敏捷迅速），其性过人（才性超过常人）——这三点，都是优点——但许由紧接着说：而又乃以人受天——然而，他以人（人为的标准）来接受天（天道）。这一句，是啮缺问题的核心：他的聪明睿知，是人的聪明——这一切，都是「人」的层面——他用「人」的标准，来理解「天」——这，是根本性的错误。"},{text:"彼审乎禁过，而不知过之所由生。",tone:"治标",guide:"这一句，是对「治标不治本」的精准批判：啮缺，知道如何禁止过失——制定规范，惩罚过失，管理行为——但他不知道：过失，从哪里产生。从《在宥》的逻辑来看：过失，从「撄人心」产生——从本性失去安顿产生——从「治天下」本身产生。啮缺，只知道禁止过失，却不知道他的「治」，本身就是过失产生的根源——这，是治者最深的盲点。"},{text:"治，乱之率也，北面之祸也，南面之贼也。",tone:"最终判决",guide:"许由，给出了一个有限的肯定——虽然，有族有祖，可以为众父而不可以为众父父（啮缺有能力，但没有根本——「众父」是引导者，「众父父」是根本的源头）。治，乱之率也——治理，是混乱的率领者——治理，导致混乱——这与《在宥》「罪在撄人心」完全呼应；北面之祸也，南面之贼也——对臣子来说，是祸害；对君主来说，是贼害——治理，对君臣双方，都是害。这三句，是《天地》对「治」的最终判决：治，不只是无效的——治，是有害的。"}]}),a[19]||(a[19]=n("h2",{id:"五、尧观华封·三辞三驳",tabindex:"-1"},[i("五、尧观华封·三辞三驳 "),n("a",{class:"header-anchor",href:"#五、尧观华封·三辞三驳","aria-label":'Permalink to "五、尧观华封·三辞三驳"'},"​")],-1)),a[20]||(a[20]=n("h3",{id:"原文-4",tabindex:"-1"},[i("原文 "),n("a",{class:"header-anchor",href:"#原文-4","aria-label":'Permalink to "原文"'},"​")],-1)),e(t,{sections:x,glossary:b,"default-mode":"classic","aria-label":"天地·尧观华封 原文"}),a[21]||(a[21]=n("h3",{id:"生僻字词-4",tabindex:"-1"},[i("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"尧观乎华",pinyin:["huà"],meaning:"华：华山。尧巡视到华山。"},{term:"华封人",pinyin:["huà","fēng","rén"],meaning:"华山的守封之人（地方官员或守土之人）。"},{term:"请祝圣人",pinyin:["zhù"],meaning:"祝：祝愿、祝福。请允许我祝福圣人。"},{term:"使圣人寿",pinyin:["shòu"],meaning:"使：让、祝愿。祝圣人长寿。"},{term:"辞",pinyin:["cí"],meaning:"辞谢、拒绝。"},{term:"富则多事",pinyin:["fù","zé","duō","shì"],meaning:"富有了就有更多的事务（财富带来麻烦）。"},{term:"寿则多辱",pinyin:["shòu","zé","duō","rǔ"],meaning:"长寿了就有更多的屈辱（活得越久，经历的屈辱越多）。"},{term:"鹑居而彀食",pinyin:["chún","jū","gòu","shí"],meaning:"鹑居：像鹌鹑一样居处（随遇而安，不固定）；彀食：像幼鸟一样进食（随时取食，不积储）。"},{term:"鸟行而无彰",pinyin:["niǎo","xíng","wú","zhāng"],meaning:"鸟行：像鸟一样行走（自由，不留痕迹）；无彰：没有彰显（不留名声）。"},{term:"退已",pinyin:["tuì","yǐ"],meaning:"退下吧！（已：语气词，表示坚决）"}]}),a[22]||(a[22]=n("h3",{id:"核心句引读-4",tabindex:"-1"},[i("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"始也我以女为圣人邪，今然君子也",subtitle:"圣人，不计算——圣人，不问「这对我的德有没有好处」。",lines:[{text:"尧曰：多男子则多惧，富则多事，寿则多辱。是三者，非所以养德也，故辞。",tone:"养德",guide:"华封人，连续三次祝福——寿·富·多男子——尧，连续三次拒绝——辞·辞·辞。尧的回答：多男子则多惧，富则多事，寿则多辱——是三者，非所以养德也，故辞。尧的逻辑，是「养德」的逻辑——一切以德为标准——对德有害的，拒绝。看起来，尧的回答很高尚——但华封人，对尧的回答，给出了更深的批判。"},{text:"封人曰：始也我以女为圣人邪，今然君子也。",tone:"君子",guide:"这一句，是华封人对尧的最深批判——圣人，高于君子——尧，只是君子，不是圣人——为什么？因为尧的逻辑，还停留在「养德」的层面——还在计算：这对我的德有没有好处——还在以「德」为目标——这，是君子的逻辑，不是圣人的逻辑。圣人，不计算——圣人，不问「这对我的德有没有好处」——因为圣人，已经超越了这个层面。"},{text:"夫圣人，鹑居而彀食，鸟行而无彰。天下有道，则与物皆昌；天下无道，则修德就闲。",tone:"圣人",guide:"华封人，描绘真正的圣人——鹑居而彀食（像鹌鹑一样居处，像幼鸟一样进食——不执着于居所，不积储食物），鸟行而无彰（像鸟一样行走，没有彰显——不留痕迹，不留名声）。天下有道，则与物皆昌（不是独自昌盛，而是与物皆昌——顺应天下，与万物同流）；天下无道，则修德就闲（不是强行改变天下，而是退而修德）。尧，还在计算——这对我的德有没有好处——华封人的圣人，不计算——随遇而安，与物皆昌——这，才是真正的圣人。"}]}),a[23]||(a[23]=n("h2",{id:"六、伯成子高·辞诸侯而耕",tabindex:"-1"},[i("六、伯成子高·辞诸侯而耕 "),n("a",{class:"header-anchor",href:"#六、伯成子高·辞诸侯而耕","aria-label":'Permalink to "六、伯成子高·辞诸侯而耕"'},"​")],-1)),a[24]||(a[24]=n("h3",{id:"原文-5",tabindex:"-1"},[i("原文 "),n("a",{class:"header-anchor",href:"#原文-5","aria-label":'Permalink to "原文"'},"​")],-1)),e(t,{sections:c,glossary:f,"default-mode":"classic","aria-label":"天地·伯成子高 原文"}),a[25]||(a[25]=n("h3",{id:"生僻字词-5",tabindex:"-1"},[i("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"伯成子高",pinyin:["bó","chéng","zǐ","gāo"],meaning:"传说中的人物，尧时的诸侯，后辞官归耕。"},{term:"立为诸侯",pinyin:["lì","wéi","zhū","hóu"],meaning:"被立为诸侯（接受封赏）。"},{term:"禹趋就下风",pinyin:["qū","jiù","xià","fēng"],meaning:"趋：快步走；就下风：走到下风处（表示恭敬）。"},{term:"不赏而民劝",pinyin:["quàn"],meaning:"劝：勉励、努力。不奖赏，百姓自然努力。"},{term:"不罚而民畏",pinyin:["bù","fá","ér","mín","wèi"],meaning:"不惩罚，百姓自然敬畏。"},{term:"德自此衰",pinyin:["dé","zì","cǐ","shuāi"],meaning:"德性从此衰败。"},{term:"刑自此立",pinyin:["xíng","zì","cǐ","lì"],meaning:"刑罚从此建立。"},{term:"夫子阖行邪",pinyin:["hé","xíng","yé"],meaning:"阖：何不、还是。你还是走吧！"},{term:"无落吾事",pinyin:["luò"],meaning:"落：耽误、妨碍。不要耽误我的事！"}]}),a[26]||(a[26]=n("h3",{id:"核心句引读-5",tabindex:"-1"},[i("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"今子赏罚而民且不仁，德自此衰，刑自此立，后世之乱自此始矣",subtitle:"赏罚，不是解决问题的方法——赏罚，反而制造了问题。",lines:[{text:"昔者尧治天下，不赏而民劝，不罚而民畏。今子赏罚而民且不仁，德自此衰，刑自此立，后世之乱自此始矣！",tone:"赏罚",guide:"伯成子高的回答，是四则寓言中最直接的批判——从前尧治天下，不奖赏，百姓自然努力；不惩罚，百姓自然敬畏。现在你用赏罚，百姓反而不仁了——这一句，是《天地》对「赏罚」最直接的批判——与《在宥》「举天下以赏其善者不足，举天下以罚其恶者不给」完全呼应：赏罚，不是解决问题的方法——赏罚，反而制造了问题——因为赏罚，是对本性的干涉——有了赏，人才开始为赏而行善——有了罚，人才开始为避罚而行善——这，不是真正的善，而是功利的善——真正的善，消失了。"},{text:"夫子阖行邪？无落吾事！俋俋乎耕而不顾。",tone:"不回头",guide:"这个结尾，与华封人「退已」异曲同工——都是两个字，都是坚决的拒绝——都是在说完最重要的话之后，不再多说，不再回头。伯成子高，不是愤怒——而是：已经说完了，该做的事还要做——耕田，才是他的事——天下的治乱，不是他的事了。"}]}),a[27]||(a[27]=n("h2",{id:"七、泰初有无",tabindex:"-1"},[i("七、泰初有无 "),n("a",{class:"header-anchor",href:"#七、泰初有无","aria-label":'Permalink to "七、泰初有无"'},"​")],-1)),a[28]||(a[28]=n("h3",{id:"原文-6",tabindex:"-1"},[i("原文 "),n("a",{class:"header-anchor",href:"#原文-6","aria-label":'Permalink to "原文"'},"​")],-1)),e(t,{sections:k,glossary:z,"default-mode":"classic","aria-label":"天地·泰初有无 原文"}),a[29]||(a[29]=n("h3",{id:"生僻字词-6",tabindex:"-1"},[i("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-6","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"泰初",pinyin:["tài","chū"],meaning:"泰：极、最。泰初：最初、太初，宇宙的最初状态。"},{term:"有无",pinyin:["yǒu","wú"],meaning:"有：存在；无：不存在。泰初的状态是「有无」——有，但是无（有存在，但无形无名）。"},{term:"无有无名",pinyin:["wú","yǒu","wú","míng"],meaning:"没有「有」，没有「名」——无形无名的状态。"},{term:"一之所起",pinyin:["yī","zhī","suǒ","qǐ"],meaning:"「一」（道的本体）开始生起的地方。"},{term:"有一而未形",pinyin:["yǒu","yī","ér","wèi","xíng"],meaning:"有了「一」，但还没有形体。"},{term:"未形者有分",pinyin:["fèn"],meaning:"分：分化、区分。还没有形体，但已经有了分化（阴阳的分化）。"},{term:"留动而生物",pinyin:["liú","dòng"],meaning:"留：流动、停留；动：运动。流动而生成万物。"},{term:"性修反德",pinyin:["xiū","fǎn"],meaning:"修：修养；反：返回。修养本性，返回于德。"},{term:"德至同于初",pinyin:["dé","zhì","tóng","yú","chū"],meaning:"德达到极致，与最初（泰初）相同。"},{term:"合喙鸣",pinyin:["hé","huì","míng"],meaning:"合：合拢；喙：嘴。合拢嘴，不鸣叫（沉默）。"},{term:"其合缗缗",pinyin:["mín","mín"],meaning:"缗缗：连绵不断、混沌一体的样子。它的合，是连绵不断的。"},{term:"若愚若昏",pinyin:["ruò","yú","ruò","hūn"],meaning:"像愚钝，像昏昧（外表看似愚昏，实则与道合一）。"},{term:"玄德",pinyin:["xuán","dé"],meaning:"深远幽暗的德，最高的德。"},{term:"同乎大顺",pinyin:["dà","shùn"],meaning:"大顺：与天地万物完全顺应。与大顺相同。"}]}),a[30]||(a[30]=n("h3",{id:"核心句引读-6",tabindex:"-1"},[i("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-6","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"泰初有无——宇宙生成论与回归序列",subtitle:"生成，是从无到有，从一到多；回归，是从多到一，从有到无。",lines:[{text:"泰初有无，无有无名。一之所起，有一而未形。",tone:"生成",guide:"第7段，是《天地》全篇最重要的哲学段落——也是《庄子》外篇中，对宇宙生成论描述最完整的一段。泰初有无——宇宙最初的状态，是「有无」——不是「有」，也不是「无」——而是「有无」——有，但是无——存在，但无形无名。无有无名——没有「有」，没有「名」——无形，无名，无分别——这是《老子》「无名，天地之始」的呼应。一之所起，有一而未形——「一」（道的本体）开始生起——有了「一」，但还没有形体——这是《老子》「道生一，一生二，二生三，三生万物」的第一步：道生一。"},{text:"物得以生谓之德；未形者有分，且然无间谓之命；留动而生物，物成生理谓之形；形体保神，各有仪则谓之性。",tone:"四定义",guide:"四句，定义四个核心概念——德·命·形·性：物得以生谓之德（德，在这里的定义极为根本：不是道德的德，而是万物从道那里得到的、使它们能够生长的那个东西——德，是道在万物中的体现）；未形者有分，且然无间谓之命（命，是形体出现之前，已经存在的那个自然的分化与流动）；留动而生物，物成生理谓之形（形，包含了外在的形状与内在的条理）；形体保神，各有仪则谓之性（性，是每个存在的独特方式）。四个概念，构成一个完整的生成序列：泰初→一→德→命→形→性——从宇宙从无到有、从一到多、从无形到有形的完整过程。"},{text:"性修反德，德至同于初。同乃虚，虚乃大。",tone:"回归",guide:"生成序列之后，庄子给出了回归序列——性修反德（修养本性，返回于德），德至同于初（德达到极致，与最初相同），同乃虚（与初相同，就是虚），虚乃大（虚空，就是大）。这四句，是整个宇宙生成论的逆向：生成方向：泰初→一→德→命→形→性；回归方向：性→修→反德→同于初→虚→大。生成，是从无到有，从一到多；回归，是从多到一，从有到无。「性修反德」——不是抛弃形体，不是逃离世界——而是在形体之中，修养本性——修养到极致，自然返回于德——这，是《天地》对修道路径的最完整描述：不需要离开世界——在世界中修养本性——自然回归到泰初的虚大。"}]}),a[31]||(a[31]=n("h2",{id:"八、夫子问老聃·将闾葂见季彻",tabindex:"-1"},[i("八、夫子问老聃·将闾葂见季彻 "),n("a",{class:"header-anchor",href:"#八、夫子问老聃·将闾葂见季彻","aria-label":'Permalink to "八、夫子问老聃·将闾葂见季彻"'},"​")],-1)),a[32]||(a[32]=n("h3",{id:"原文-7",tabindex:"-1"},[i("原文 "),n("a",{class:"header-anchor",href:"#原文-7","aria-label":'Permalink to "原文"'},"​")],-1)),e(t,{sections:P,glossary:q,"default-mode":"classic","aria-label":"天地·夫子问老聃 原文"}),a[33]||(a[33]=n("h3",{id:"生僻字词-7",tabindex:"-1"},[i("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-7","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"治道若相放",pinyin:["xiāng","fǎng"],meaning:"相放：相仿、模仿。治道，好像在模仿（道）。"},{term:"离坚白",pinyin:["lí","jiān","bái"],meaning:"离：分离。坚白：坚硬与白色（公孙龙的「坚白论」）。"},{term:"若县寓",pinyin:["ruò","xuán","yù"],meaning:"县：通「悬」，悬挂；寓：寄寓。像悬挂在空中一样（高悬而不落地，脱离实际）。"},{term:"胥易技系",pinyin:["xū","yì","jì","xì"],meaning:"胥：相互；易：变换；技：技巧；系：束缚。相互变换技巧，被技巧所束缚。"},{term:"劳形怵心",pinyin:["chù","xīn"],meaning:"怵：恐惧、惊惧。劳累形体，惊惧内心。"},{term:"将闾葂",pinyin:["jiāng","lǘ","miǎn"],meaning:"庄子虚构的人物，向季彻请教。"},{term:"季彻",pinyin:["jì","chè"],meaning:"庄子虚构的人物，得道之人。"},{term:"必服恭俭",pinyin:["bì","fú","gōng","jiǎn"],meaning:"必须身着恭俭（以恭俭为表率）。"},{term:"无阿私",pinyin:["ē","sī"],meaning:"阿私：偏袒私情。不偏袒私情。"},{term:"摇荡民心",pinyin:["yáo","dàng","mín","xīn"],meaning:"摇动、感化民心（非强制，而是自然感化）。"}]}),a[34]||(a[34]=n("h3",{id:"核心句引读-7",tabindex:"-1"},[i("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-7","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"忘乎物，忘乎天，其名为忘己——入于天",subtitle:"辩者以为在追求道，实则被自己的辩论技巧所束缚——技巧，成了枷锁。",lines:[{text:"是胥易技系，劳形怵心者也。执留之狗成思，猿狙之便自山林来。",tone:"技系",guide:"夫子（孔子）问老聃：有人治道若相放，可不可，然不然——辩者有言曰：离坚白，若县寓——若是则可谓圣人乎？老聃的回答，极为直接——是胥易技系，劳形怵心者也——这是相互变换技巧、被技巧所束缚，劳累形体、惊惧内心的人。「胥易技系」——辩者，以为自己在追求道——实则，被自己的辩论技巧所束缚——技巧，成了枷锁。「执留之狗成思，猿狙之便自山林来」——被拴住的狗整天思虑，猿猴的灵便来自山林——离开了本然的环境，灵便就消失了。"},{text:"忘乎物，忘乎天，其名为忘己。忘己之人，是之谓入于天。",tone:"忘己",guide:"有治在人——治理，在于人。忘乎物，忘乎天，其名为忘己——忘掉外物，忘掉天，这叫做忘己——忘己之人，是之谓入于天——忘己的人，这叫做进入天（与天合一）。「忘己」——不是消灭自我——而是：不再执着于「我」与「物」的分别——忘记那个以自我为中心的「我」——这，与《人间世》的「吾丧我」、《大宗师》的「堕肢体，黜聪明」完全呼应——入于天，不是离开人间，而是放下执着，与天地合一。"}]}),a[35]||(a[35]=n("h2",{id:"九、子贡遇丈人·机心·全德之人",tabindex:"-1"},[i("九、子贡遇丈人·机心·全德之人 "),n("a",{class:"header-anchor",href:"#九、子贡遇丈人·机心·全德之人","aria-label":'Permalink to "九、子贡遇丈人·机心·全德之人"'},"​")],-1)),a[36]||(a[36]=n("h3",{id:"原文-8",tabindex:"-1"},[i("原文 "),n("a",{class:"header-anchor",href:"#原文-8","aria-label":'Permalink to "原文"'},"​")],-1)),e(t,{sections:w,glossary:j,"default-mode":"classic","aria-label":"天地·子贡遇丈人 原文"}),a[37]||(a[37]=n("h3",{id:"生僻字词-8",tabindex:"-1"},[i("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-8","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"汉阴",pinyin:["hàn","yīn"],meaning:"汉水的南边。"},{term:"为圃畦",pinyin:["pǔ","qí"],meaning:"圃：菜园；畦：菜畦。做菜园的畦。"},{term:"凿隧而入井",pinyin:["záo","suì","ér","rù","jǐng"],meaning:"凿一条隧道通到井里。"},{term:"抱瓮而出灌",pinyin:["wèng"],meaning:"瓮：陶罐。抱着陶罐出来浇灌。"},{term:"凿木为机",pinyin:["záo","mù","wéi","jī"],meaning:"凿木做成机械（桔槔）。"},{term:"挈水若抽",pinyin:["qiè"],meaning:"挈：提起。提水就像抽水一样。"},{term:"数如泆汤",pinyin:["yì","tāng"],meaning:"泆：溢出。迅速得像沸汤溢出一样。"},{term:"其名为槔",pinyin:["gāo"],meaning:"槔：桔槔（杠杆提水工具）。"},{term:"博学以拟圣",pinyin:["bó","xué","yǐ","nǐ","shèng"],meaning:"博学来比拟圣人——学了很多，但只是在模仿圣人。"},{term:"於于以盖众",pinyin:["yú","yú"],meaning:"於于：自鸣得意。自鸣得意地压过众人。"},{term:"全德之人",pinyin:["quán","dé","zhī","rén"],meaning:"德性完整的人。"},{term:"浑沌氏之术",pinyin:["hún","dùn","shì"],meaning:"浑沌氏（上古帝王）的方术。"}]}),a[38]||(a[38]=n("h3",{id:"核心句引读-8",tabindex:"-1"},[i("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-8","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"有机械者必有机事，有机事者必有机心",subtitle:"机心一旦进入，纯白就被侵蚀——纯白不备则神生不定，神生不定者，道之所不载也。",lines:[{text:"有机械者必有机事，有机事者必有机心。机心存于胸中则纯白不备。纯白不备则神生不定，神生不定者，道之所不载也。吾非不知，羞而不为也。",tone:"机心",guide:"子贡南游于楚，见一丈人抱瓮而出灌，搰然用力甚多而见功寡。子贡说：有械于此，一日浸百畦——丈人忿然作色而笑：吾闻之吾师，有机械者必有机事，有机事者必有机心——机心存于胸中则纯白不备——纯白不备则神生不定——神生不定者，道之所不载也——吾非不知，羞而不为也。这个逻辑链，是《天地》最著名的机心论：机械（工具）→机事（取巧的事）→机心（机巧算计的心）→纯白不备（本真破损）→神生不定（精神动荡）→道之所不载（与道隔绝）。丈人不是无知，而是有知而不为——知道桔槔，但羞于使用——因为使用桔槔，会带来机心——机心，会破坏纯白。"},{text:"非其志不之，非其心不为。虽以天下誉之，得其所谓，謷然不顾；以天下非之，失其所谓，傥然不受。天下之非誉无益损焉，是谓全德之人哉！",tone:"全德",guide:"子贡被丈人震撼，行三十里而后愈。他反思：始吾以为天下一人耳，不知复有夫人也——执道者德全，德全者形全，形全者神全。若夫人者，非其志不之，非其心不为——虽以天下誉之，謷然不顾；以天下非之，傥然不受——天下之非誉无益损焉，是谓全德之人哉！全德之人——天下称赞他，他不在意；天下非议他，他不接受——不是因为麻木，而是因为：他的根基，不在天下人的评价中——他的根基，在道与德中。"},{text:"彼假修浑沌氏之术者也。识其一，不识其二；治其内而不治其外。夫明白入素，无为复朴，体性抱神，以游世俗之间者，汝将固惊邪？",tone:"中间路",guide:"反于鲁，以告孔子。孔子曰：彼假修浑沌氏之术者也——识其一，不识其二——治其内而不治其外——丈人，拒绝桔槔，守住了纯白——但他，只治内，不治外——他，不是完整的圣人。真正的圣人，是：明白入素，无为复朴，体性抱神，以游世俗之间者——这，就是中间路：不是拒绝世俗（丈人的路），不是沉溺世俗（机心的路）——而是在世俗中游走，同时保持明白·入素·无为·复朴·体性·抱神。连孔子都承认：且浑沌氏之术，予与汝何足以识之哉！"}]}),a[39]||(a[39]=n("h2",{id:"十、谆芒论三境·圣治·德人·神人",tabindex:"-1"},[i("十、谆芒论三境·圣治·德人·神人 "),n("a",{class:"header-anchor",href:"#十、谆芒论三境·圣治·德人·神人","aria-label":'Permalink to "十、谆芒论三境·圣治·德人·神人"'},"​")],-1)),a[40]||(a[40]=n("h3",{id:"原文-9",tabindex:"-1"},[i("原文 "),n("a",{class:"header-anchor",href:"#原文-9","aria-label":'Permalink to "原文"'},"​")],-1)),e(t,{sections:T,glossary:G,"default-mode":"classic","aria-label":"天地·谆芒论三境 原文"}),a[41]||(a[41]=n("h3",{id:"生僻字词-9",tabindex:"-1"},[i("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-9","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"谆芒",pinyin:["zhūn","máng"],meaning:"庄子虚构的人物，得道者。"},{term:"大壑",pinyin:["dà","hè"],meaning:"大海（极深的沟壑）。"},{term:"苑风",pinyin:["yuàn","fēng"],meaning:"庄子虚构的人物。"},{term:"横目之民",pinyin:["héng","mù"],meaning:"横目：眼睛横着长的人（人）。指百姓。"},{term:"手挠顾指",pinyin:["ráo","gù","zhǐ"],meaning:"挠：挥动；顾：回头。挥动手，回过头指点（从容指挥）。"}]}),a[42]||(a[42]=n("h3",{id:"核心句引读-9",tabindex:"-1"},[i("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-9","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"圣治·德人·神人——三境",subtitle:"圣治：官施不失其宜；德人：居无思行无虑；神人：与天地乐而万事销亡。",lines:[{text:"圣治乎？官施而不失其宜，拔举而不失其能，毕见其情事而行其所为，行言自为而天下化。",tone:"圣治",guide:"谆芒将东之大壑（大海），适遇苑风于东海之滨。大壑之为物也，注焉而不满，酌焉而不竭——往里注入而不满，从里取出而不竭——这是大海的象征，也是道的象征。苑风问三境：愿闻圣治——谆芒曰：圣治乎？官施而不失其宜（设官施政不失其适宜），拔举而不失其能（提拔举荐不失其才能），毕见其情事而行其所为（完全看清事物的实情，然后做该做的事）——行言自为而天下化（行动与言论自然而为，天下自然被感化）。圣治，不是强制安排，而是让事物自然归位。"},{text:"德人者，居无思，行无虑，不藏是非美恶。四海之内共利之之谓悦，共给之之谓安。",tone:"德人",guide:"愿闻德人——德人者，居无思，行无虑（居处没有思虑，行动没有忧虑），不藏是非美恶（内心不藏是非美恶）——四海之内共利之之谓悦（四海之内共同得利，叫做悦），共给之之谓安（共同给养，叫做安）——财用有余而不知其所自来（财用有余却不知道从哪里来），饮食取足而不知其所从（饮食充足却不知道从何处来）——此谓德人之容。德人——本然自足，不计算，不执着——连财用从哪里来都不知道——不是无知，而是：不需要知道。"},{text:"上神乘光，与形灭亡，是谓照旷。致命尽情，天地乐而万事销亡，万物复情，此之谓混溟。",tone:"神人",guide:"愿闻神人——上神乘光（最高的神人乘着光明），与形灭亡（与形体一同消亡）——是谓照旷（这叫做照旷——照彻空旷）。致命尽情（穷尽天命与性情），天地乐而万事销亡（天地同乐而万事消融）——万物复情（万物复归本情）——此之谓混溟（这叫做混溟——混沌溟漠）。神人——与形灭亡，不是肉体的消灭，而是：不再执着于形体——乘光而行，与天地同乐——这，是《逍遥游》「神人」境界在《天地》中的回响。"}]}),a[43]||(a[43]=n("h2",{id:"十一、门无鬼·赤张满稽·至德之世",tabindex:"-1"},[i("十一、门无鬼·赤张满稽·至德之世 "),n("a",{class:"header-anchor",href:"#十一、门无鬼·赤张满稽·至德之世","aria-label":'Permalink to "十一、门无鬼·赤张满稽·至德之世"'},"​")],-1)),a[44]||(a[44]=n("h3",{id:"原文-10",tabindex:"-1"},[i("原文 "),n("a",{class:"header-anchor",href:"#原文-10","aria-label":'Permalink to "原文"'},"​")],-1)),e(t,{sections:D,glossary:C,"default-mode":"classic","aria-label":"天地·至德之世 原文"}),a[45]||(a[45]=n("h3",{id:"生僻字词-10",tabindex:"-1"},[i("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-10","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"门无鬼",pinyin:["mén","wú","guǐ"],meaning:"庄子虚构的人物。"},{term:"赤张满稽",pinyin:["chì","zhāng","mǎn","jī"],meaning:"庄子虚构的人物。"},{term:"秃而施髢",pinyin:["shī","dí"],meaning:"髢：假发。秃了头才戴假发（遮掩，不是解决）。"},{term:"病而求医",pinyin:["bìng","ér","qiú","yī"],meaning:"生了病才去求医（亡羊补牢，为时已晚）。"},{term:"其色燋然",pinyin:["jiāo","rán"],meaning:"燋然：焦虑的样子。孝子焦虑的脸色，说明父亲已经病了——这本身，就是失败。"},{term:"上如标枝",pinyin:["shàng","rú","biāo","zhī"],meaning:"君主，像树梢的枝条——高高在上，但轻盈，不压迫。"},{term:"民如野鹿",pinyin:["mín","rú","yě","lù"],meaning:"百姓，像野鹿——自由自在，不被驯化。"}]}),a[46]||(a[46]=n("h3",{id:"核心句引读-10",tabindex:"-1"},[i("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-10","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"至德之世，不尚贤，不使能，上如标枝，民如野鹿",subtitle:"端正而不知以为义——一旦有了名字，成了概念，本然就消失了。",lines:[{text:"有虞氏之药疡也，秃而施髢，病而求医。孝子操药以修慈父，其色燋然，圣人羞之。",tone:"药疡",guide:"门无鬼与赤张满稽观于武王之师。赤张满稽：不及有虞氏乎！门无鬼问：天下均治而有虞氏治之邪？其乱而后治之与？——赤张满稽答：天下均治之为愿，而何计以有虞氏为！有虞氏之药疡也——有虞氏（舜）治理天下，就像给疮疡上药——天下已经坏了，才来治。秃而施髢（秃了才戴假发），病而求医——治标，不治本。孝子操药以修慈父，其色燋然——孝子是好意的，但孝子焦虑的脸色，说明父亲已经病了——这本身，就是失败——圣人，羞于看到这种场景——因为真正的圣人，不会让天下病到需要治的程度。"},{text:"端正而不知以为义，相爱而不知以为仁，实而不知以为忠，当而不知以为信，蠢动而相使不以为赐。是故行而无迹，事而无传。",tone:"不知以为",guide:"至德之世，不尚贤，不使能，上如标枝（君主像树梢的枝条——高高在上，但轻盈，不压迫——这，是「在宥天下」的最形象的比喻），民如野鹿（百姓像野鹿——自由自在，不被驯化）。四个「不知以为」——端正·相爱·实·当——这些，都是好的——都是义·仁·忠·信的实质——但「不知以为义·仁·忠·信」——不知道这些有名字——因为：这些，是本然的——不是学来的，不是被教导的——是自然流淌的——所以，不需要名字。一旦有了名字——义·仁·忠·信，成了概念——成了可以追求的目标——成了可以用来评价别人的标准——本然，就消失了。是故行而无迹，事而无传——没有历史，没有记录，没有传说——因为：没有什么值得特别记录——一切，都是本然的——这，才是真正的「无为」。"}]}),a[47]||(a[47]=n("h2",{id:"十二、大惑论·天下皆惑",tabindex:"-1"},[i("十二、大惑论·天下皆惑 "),n("a",{class:"header-anchor",href:"#十二、大惑论·天下皆惑","aria-label":'Permalink to "十二、大惑论·天下皆惑"'},"​")],-1)),a[48]||(a[48]=n("h3",{id:"原文-11",tabindex:"-1"},[i("原文 "),n("a",{class:"header-anchor",href:"#原文-11","aria-label":'Permalink to "原文"'},"​")],-1)),e(t,{sections:v,glossary:N,"default-mode":"classic","aria-label":"天地·大惑论 原文"}),a[49]||(a[49]=n("h3",{id:"生僻字词-11",tabindex:"-1"},[i("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-11","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"不谀其亲",pinyin:["yú"],meaning:"谀：谄媚、奉承。不奉承自己的父母。"},{term:"不谄其君",pinyin:["chǎn"],meaning:"谄：谄媚。不谄媚自己的君主。"},{term:"不肖子",pinyin:["bù","xiào","zǐ"],meaning:"不肖：不像样、不孝顺。不孝顺的儿子。"},{term:"道谀之人",pinyin:["dào","yú"],meaning:"道谀：表面引导，实则奉承。"},{term:"勃然作色",pinyin:["bó","rán"],meaning:"勃然：激动地。突然变脸色（愤怒）。"},{term:"怫然作色",pinyin:["fú","rán"],meaning:"怫然：不高兴的样子。不高兴地变脸色。"},{term:"以媚一世",pinyin:["mèi"],meaning:"媚：讨好、迎合。来讨好一世之人。"},{term:"嗑然而笑",pinyin:["kē","rán"],meaning:"嗑然：开心大笑的样子。"}]}),a[50]||(a[50]=n("h3",{id:"核心句引读-11",tabindex:"-1"},[i("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-11","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"知其愚者，非大愚也；知其惑者，非大惑也",subtitle:"大惑者，终身不解；大愚者，终身不灵。",lines:[{text:"知其愚者，非大愚也；知其惑者，非大惑也。大惑者，终身不解；大愚者，终身不灵。",tone:"大惑",guide:"大惑论开篇：孝子不谀其亲，忠臣不谄其君——臣、子之盛也。但亲之所言而然，所行而善——则世俗谓之不肖子——君之所言而然，所行而善——则世俗谓之不肖臣。庄子追问：世俗之所谓然而然之，所谓善而善之——则不谓之道谀之人也！——世俗说对的就跟着说对，世俗说好的就跟着说好——却不认为这是「道谀」（奉承）——然则俗故严于亲而尊于君邪？知其愚者，非大愚也；知其惑者，非大惑也——大惑者，终身不解；大愚者，终身不灵——知道自己愚的人，不是大愚——不知道自己愚的，才是大愚——这，是「天下皆惑」的诊断：惑而不自知，才是最大的惑。"},{text:"三人行而一人惑，所适者，犹可致也，惑者少也；二人惑则劳而不至，惑者胜也。而今也以天下惑，予虽有祈向，不可得也。不亦悲乎！",tone:"天下惑",guide:"三人行而一人惑——目的地还可以到达——因为迷惑的人少；二人惑则劳而不至——因为迷惑的人占多数。而今也以天下惑——现在，天下的人都迷惑——予虽有祈向，不可得也——我虽然有祈求向往的方向，却无法到达——不亦悲乎！大声不入于里耳（高深的言论进不了俗耳），折杨、皇荂，则嗑然而笑（通俗的歌曲，反而开心大笑）——是故高言不止于众人之心；至言不出，俗言胜也。以二缶钟惑，而所适不得矣——以天下惑，予虽有祈向，其庸可得邪！知其不可得也而强之，又一惑也！故莫若释之而不推。不推，谁其比忧！——这，是《天地》最深的悲哀：道在那里，但天下皆惑，无人能识——与其强行，不如放下。"}]}),a[51]||(a[51]=n("h2",{id:"十三、失性五者·生之害",tabindex:"-1"},[i("十三、失性五者·生之害 "),n("a",{class:"header-anchor",href:"#十三、失性五者·生之害","aria-label":'Permalink to "十三、失性五者·生之害"'},"​")],-1)),a[52]||(a[52]=n("h3",{id:"原文-12",tabindex:"-1"},[i("原文 "),n("a",{class:"header-anchor",href:"#原文-12","aria-label":'Permalink to "原文"'},"​")],-1)),e(t,{sections:V,glossary:R,"default-mode":"classic","aria-label":"天地·失性五者 原文"}),a[53]||(a[53]=n("h3",{id:"生僻字词-12",tabindex:"-1"},[i("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-12","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"百年之木",pinyin:["bǎi","nián","zhī","mù"],meaning:"活了百年的树木。"},{term:"破为牺尊",pinyin:["xī","zūn"],meaning:"破：剖开。剖开做成牺尊（祭祀酒器）。"},{term:"青黄而文之",pinyin:["qīng","huáng","ér","wén","zhī"],meaning:"涂上青黄的花纹（装饰）。"},{term:"其断在沟中",pinyin:["qí","duàn","zài","gōu","zhōng"],meaning:"它的断木，被扔在沟里。"}]}),a[54]||(a[54]=n("h3",{id:"核心句引读-12",tabindex:"-1"},[i("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-12","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"百年之木——你，还是那棵树吗？",subtitle:"牺牲与沟中断木，美恶有别，其于失性一也。",lines:[{text:"百年之木，破为牺尊，青黄而文之，其断在沟中。比牺尊于沟中之断，则美恶有间矣，其于失性一也。跖与曾、史，行义有间矣，然其失性均也。",tone:"失性",guide:"失性五者开篇——百年之木，破为牺尊（精美的祭祀酒器），青黄而文之——其断在沟中（断木被扔在沟里）。比牺尊于沟中之断——则美恶有间矣（精美与粗陋有差别）——其于失性一也（但在失去本性上是一样的）。跖与曾、史，行义有间矣（盗跖与曾参、史鱼，行为善恶有差别）——然其失性均也（但失去本性是一样的）。这，是《天地》对「失性」最深的观察：无论你是被做成精美的牺尊（被社会珍视），还是被扔在沟里（被社会遗弃）——只要你的本性被改造了，你就失去了那棵百年大树的本然——你，还是那棵树吗？"},{text:"且夫失性有五：一曰五色乱目，使目不明；二曰五声乱耳，使耳不聪；三曰五臭熏鼻，困惾中颡；四曰五味浊口，使口厉爽；五曰趣舍滑心，使性飞扬。此五者，皆生之害也。",tone:"五者",guide:"失性有五：一曰五色乱目（五色扰乱眼睛，使眼睛不明）；二曰五声乱耳（五声扰乱耳朵，使耳朵不聪）；三曰五臭熏鼻（五种气味熏鼻子，使气闷而伤额头）；四曰五味浊口（五味扰乱嘴巴，使嘴巴受伤）；五曰趣舍滑心（取舍扰乱内心，使本性飞扬——失去安定）。此五者，皆生之害也——这五种，都是生命的伤害。五色·五声·五臭·五味·趣舍——五种感官刺激与取舍执着——都在损伤生命——这，与《骈拇》的「五色乱目」批判完全呼应。"},{text:"且夫趣舍声色以柴其内，皮弁鹬冠搢笏绅修以约其外。内支盈于柴栅，外重纆缴睆睆然在纆缴之中，而自以为得，则是罪人交臂历指而虎豹在于囊槛，亦可以为得矣！",tone:"笼中",guide:"杨、墨乃始离跂自以为得，非吾所谓得也——夫得者困，可以为得乎？则鸠鸮之在于笼也，亦可以为得矣（斑鸠被关在笼子里，也可以算是得了吗？）。趣舍声色以柴其内（欲望像柴草一样塞满内心），皮弁鹬冠搢笏绅修以约其外（礼法像绳索一样束缚外表）——内支盈于柴栅，外重纆缴——在枷锁之中，而自以为得——则是罪人交臂历指而虎豹在于囊槛，亦可以为得矣（罪人被反绑双手、虎豹被关在笼子里，也可以算是得了吗？）。这，是《天地》对「自以为得」最深的讽刺：那些自以为得道的人——其实是被欲望与礼法双重捆绑的囚徒。"}]}),a[55]||(a[55]=I("",34))])}}});export{U as __pageData,F as default};
